# -*- coding: utf-8 -*-
# 源文件: src/components/tasks/BackgroundTasksDialog.tsx
ANNOTATIONS = [
    (1, 'before', '本文件是后台任务总管对话框（/tasks 入口）：把七类后台任务（本地 shell、远程代理、本地代理、进程内队友、工作流、MCP 监视器、dream）统一列进一个可导航列表，Enter 进详情、x 停止、f 前台化。文件由 React Compiler 编译，主组件外的 Item / TeammateTaskGroups 是编译出的子组件，尾部 _temp / _temp2 是提升出来的谓词。'),
    (43, 'before', 'ViewState：两种形态——list 是总列表，detail 是按任务 id 进详情。用单个状态对象而非布尔标记，避免「列表 + 详情同时存在」的非法中间态。'),
    (49, 'before', 'Props：onDone 关闭对话框并上报结果文案；initialDetailTaskId 允许调用方直接跳进某个任务的详情（如通知点击直达）。'),
    (56, 'before', 'ListItem：七类任务加上 leader（队长入口）的可辨识联合。每类带各自的 task 状态快照（DeepImmutable 包裹，防止列表渲染时误改），type 字段驱动后续的停止与详情分派。'),
    (105, 'before', '特性门控的动态 require：WORKFLOW_SCRIPTS 是 ant 内部特性（构建旗标），静态 import 会把约 1.3K 行泄漏进外部构建，所以用 feature() + require 让打包器死代码消除整条分支。注意 116 行注释的坑：require 路径必须用相对路径，src/... 路径映射字符串 Bun 的 DCE 解析不了，会作为死字面量残留在产物里。'),
    (114, 'before', 'MonitorMcp 同样走特性门控（MONITOR_TOOL）。这一段是「可选功能不进发行包」的通用模式：模块、对话框、kill 函数三者都要门控，缺一个就漏。'),
    (123, 'before', 'getSelectableBackgroundTasks：从全局任务表里筛出后台任务，并排除正在前台展示的 local_agent——它已在主界面显示，再进列表会重复。'),
    (127, 'before', 'BackgroundTasksDialog 主组件。'),
    (140, 'after', 'skippedListOnMount：记录挂载时是否跳过了列表页（调用方直达详情，或恰好只有一个任务自动直达）。它决定返回键是「回列表」还是「直接关对话框」。用 ref 而非 state，因为它只是行为标记，不需要触发重渲染。'),
    (144, 'before', '初始视图惰性求值：有指定任务或只有一个可选任务就直接进详情。一个任务也自动跳详情是刻意设计——单独弹个列表再选一次太浪费交互。'),
    (168, 'after', 'useRegisterOverlay：注册成模态覆盖层，挂起父级 Chat 的上下键（历史回溯）等快捷键，避免两层键盘处理打架。'),
    (222, 'after', 'allSelectableItems 的顺序契约：必须与下方 JSX 的分组渲染顺序一致（队友 → shell → 监视器 → 远程 → 本地代理 → 工作流 → dream），否则上下键移动的光标与视觉位置错位。这是本文件最脆弱的隐式约定，改渲染顺序必须同步改这里。'),
    (223, 'after', 'currentSelection：selectedIndex 越界时落 null，渲染与键盘处理都要容忍空值。'),
    (227, 'before', '标准导航走可配置键绑定（confirm:previous / next / yes），只在 list 模式激活；详情模式下这些键交回给详情对话框。'),
    (253, 'before', 'handleKeyDown：组件专属快捷键（x 停止、f 前台化、左键关闭）。这些是任务类型与状态相关的动作，不适合进全局键绑定表，所以用原生 onKeyDown。'),
    (268, 'before', 'x 键的停止分派：按任务类型调各自的 kill 静态方法。远程代理再分叉——ultraplan 会话要走 stopUltraplan（要连带清理计划状态），普通远程代理直接 kill。每支都先查 status 是否 running，停掉的任务再按 x 无效。'),
    (290, 'before', 'f 键：进程内队友进其专属视图（enterTeammateView），leader 则退出队友视图回到队长本体。这是多智能体 swarm 的视图切换入口。'),
    (306, 'before', '五个 kill 辅助函数：纯粹是给各类任务的静态 kill 包一层 async 语法糖（void 调用不阻塞键盘处理）。分开写而非用一个 map 分派，是为了类型收窄——每类的 task 状态形状不同。'),
    (324, 'after', 'onDoneEvent：useEffectEvent 包装 onDone，得到「引用稳定但永远调最新回调」的函数——下面的 useEffect 依赖它不会反复重跑，调用时又不会捕获旧闭包。这是 React 官方为「事件与 effect 解耦」提供的原语。'),
    (354, 'before', 'goBackToList：返回列表或关闭对话框的判定。注意注释里的过期状态陷阱：如果挂载时只有 1 个任务（自动跳过了列表），之后第二个任务启动了，此时按返回应该看到列表而不是关掉对话框——所以要用当前数量重新判定，不能只看 skippedListOnMount。'),
    (368, 'before', '详情模式分派：按任务类型渲染对应的详情对话框，每个都用 key 绑定任务 id，任务切换时强制重建组件内部状态。workflow 与 monitor 的对话框可能是 null（特性门控未开），渲染前判空。'),
    (403, 'after', '统计各组的运行数，拼成副标题（如 2 agents · 1 active shell · 3 active agents），单复数在 JSX 里处理。'),
    (492, 'before', 'toListItem：TaskState 到 ListItem 的映射。label 按类型取最语义化的字段：shell 用命令行（monitor 型用描述）、远程用标题、队友加 @ 前缀、工作流优先 summary。'),
    (552, 'before', 'Item：列表行。maxActivityWidth 按终端列数自适应（至少 30 列），coordinator 模式下选中行用灰指针（isCoordinatorMode 只调一次，缓存在记忆槽 0——这是编译器把「运行时不变量」提升到首次渲染求值的例子）。'),
    (612, 'before', 'TeammateTaskGroups：把队友按 teamName 分组展示，leader 条目在每个组头重复出现（key 带 teamName 后缀避免重复）。'),
    (620, 'after', '分组逻辑：leader 条目单列（type 等于 leader 的谓词在 _temp），其余按 identity.teamName 进 Map，再展开成组数组。成员数 = 组员 + leader（每个组都算上队长）。'),
]
